<?php
// Unified Admin Control Center, U1, DATABASE-FREE: navigation registry and role visibility, active states, breadcrumbs, environment banner, shell markup and safeguards,
// sign-in page, account page and the self-service password change (policy, rate limit, audit, own account only), plus static checks. No database, no server.
$root = dirname(__DIR__); chdir($root);
ob_start(); require_once $root . '/helpers.php'; require_once $root . '/crm_views.php'; require_once $root . '/adm_core.php'; require_once $root . '/adm_tools_views.php'; require_once $root . '/adm_finance_views.php'; require_once $root . '/adm_auth.php'; require_once $root . '/adm_account.php'; ob_end_clean();
$pass = 0; $fail = 0; function ok($c, string $m): void { global $pass, $fail; if ($c) $pass++; else { $fail++; fwrite(STDERR, "  FAIL: $m\n"); } }
$roles = ['owner', 'sales', 'viewer', 'editor', 'verifier']; $labelsOf = function (string $role, string $cur = 'dashboard', array $get = []) { $o = []; foreach (adm_nav_tree($role, $cur, $get) as $g) foreach ($g['items'] as $i) $o[] = $i['label']; return $o; };

// ---- visibility matrix: the menu only shows what the role may open ----
$exp = ['owner' => ['Overview', 'CRM and leads', 'AI tool management', 'AI Universe review', 'Tool profile verification', 'Legacy admin', 'Analytics', 'Advertising', 'Finance and revenue', 'Affiliate revenue', 'Users, roles and audit', 'Operations', 'Performance', 'Account and password'],
  'sales' => ['Overview', 'CRM and leads', 'Advertising', 'Account and password'], 'viewer' => ['Overview', 'CRM and leads', 'Account and password'],
  'editor' => ['Overview', 'AI tool management', 'AI Universe review', 'Tool profile verification', 'Account and password'], 'verifier' => ['Overview', 'AI Universe review', 'Tool profile verification', 'Account and password']];
foreach ($exp as $r => $want) { $got = $labelsOf($r); sort($want); $g2 = $got; sort($g2); ok($g2 === $want, "$r sees exactly: " . implode(', ', $want) . ($g2 === $want ? '' : ' (got ' . implode(', ', $got) . ')')); }
ok($labelsOf('nobody') === [] && $labelsOf('') === [], 'an unknown role sees no navigation at all');
foreach ($roles as $r) foreach (adm_modules() as $id => $m) { $has = adm_can($r, $m['perm']); $shown = in_array($m['label'], $labelsOf($r), true); ok($has === $shown, "$r: '$id' is shown exactly when the permission is held"); }
ok(!array_filter(adm_nav_tree('editor'), fn($g) => in_array($g['id'], ['money', 'growth', 'ops', 'sales'], true)), 'an editor has no Money, Growth, Operations or Sales groups');
ok(array_column(adm_nav_tree('verifier'), 'id') === ['overview', 'content', 'account'], 'empty groups are hidden (a verifier sees Overview, Content and Account only)');
$fin = array_filter(adm_nav_tree('owner', 'finance'), fn($g) => $g['id'] === 'money'); $fi = array_values($fin)[0]['items'][0]; ok(count($fi['children']) === 8 && $fi['children'][0]['label'] === 'Overview', 'the active module lists its sub-views (finance: 8)');
$other = adm_nav_tree('owner', 'operations'); $kids = 0; foreach ($other as $g) foreach ($g['items'] as $i) $kids += count($i['children']); ok($kids === 0, 'inactive modules show no sub-views (keeps the menu short)');
foreach (adm_nav_tree('owner') as $g) foreach ($g['items'] as $i) { if ($i['external']) ok(in_array($i['id'], ['crm', 'universe', 'legacy'], true), "{$i['id']} is marked as opening its own page (until later milestones embed it)"); }
$ct = adm_nav_tree('editor', 'tools', ['view' => 'submissions']); $tc = array_values(array_filter($ct, fn($g) => $g['id'] === 'content'))[0]['items'][0]['children']; ok(array_column(array_filter($tc, fn($c) => $c['active']), 'label') === ['Submissions'], 'the active sub-view is marked (tools, submissions)');
$tc = array_values(array_filter(adm_nav_tree('editor', 'tools', []), fn($g) => $g['id'] === 'content'))[0]['items'][0]['children']; ok(array_column(array_filter($tc, fn($c) => $c['active']), 'label') === ['Tools'], 'with no view selected the default sub-view is active');
$tc = array_values(array_filter(adm_nav_tree('editor', 'tools', ['view' => 'nonsense']), fn($g) => $g['id'] === 'content'))[0]['items'][0]['children']; ok(array_column(array_filter($tc, fn($c) => $c['active']), 'label') === ['Tools'], 'an unknown view falls back to the default without error');
ok(array_values(array_filter(adm_nav_tree('owner', 'finance'), fn($g) => $g['active']))[0]['id'] === 'money', 'the group of the active module is marked active');
foreach (adm_modules() as $id => $m) ok(isset($m['label'], $m['perm']) && !empty($m['href'] ?? '/admin-center.php?m=' . $id), "module $id has a label, a permission and an address");

// ---- breadcrumbs ----
ok(adm_breadcrumbs('dashboard', [], 'owner') === [['label' => 'Control Center']], 'breadcrumb on the overview is a single current item');
$bc = adm_breadcrumbs('finance', ['view' => 'revenue'], 'owner'); ok(array_column($bc, 'label') === ['Control Center', 'Money', 'Finance and revenue', 'Revenue'] && isset($bc[0]['href']) && isset($bc[2]['href']) && !isset($bc[3]['href']), 'breadcrumb: Control Center / Money / Finance and revenue / Revenue, last item is current');
ok(array_column(adm_breadcrumbs('finance', [], 'owner'), 'label') === ['Control Center', 'Money', 'Finance and revenue'], 'breadcrumb without a sub-view ends at the module');
ok(array_column(adm_breadcrumbs('finance', ['view' => 'revenue'], 'editor'), 'label') === ['Control Center'], 'breadcrumb never reveals a module the role may not see');
$html = adm_crumbs_html(adm_breadcrumbs('finance', ['view' => 'revenue'], 'owner')); ok(strpos($html, 'aria-label="Breadcrumb"') !== false && substr_count($html, 'aria-current="page"') === 1 && substr_count($html, '<li>') === 4, 'breadcrumb markup: labelled nav, ordered list, one current item');

// ---- environment banner (D8) ----
$setEnv = function (?string $v) { if ($v === null) putenv('AIHUB_ENV_LABEL'); else putenv('AIHUB_ENV_LABEL=' . $v); };
$setEnv('staging'); $h = adm_env_html(); ok(strpos($h, 'admEnv-staging') !== false && strpos($h, '>STAGING<') !== false && strpos($h, 'role="note"') !== false, 'staging banner: amber class and the word STAGING');
$setEnv('production'); $h = adm_env_html(); ok(strpos($h, 'admEnv-production') !== false && strpos($h, '>PRODUCTION<') !== false, 'production banner: red class and the word PRODUCTION');
$setEnv('  Staging '); ok(adm_env()['key'] === 'staging', 'the setting is trimmed and case-insensitive');
foreach (['', 'prod', 'live', '<script>alert(1)</script>', 'staging; production'] as $bad) { $setEnv($bad); ok(adm_env()['key'] === 'unset' && strpos(adm_env_html(), '<script>') === false && strpos(adm_env_html(), 'ENVIRONMENT NOT SET') !== false, 'an unknown or hostile setting shows "environment not set": ' . json_encode($bad)); }
$setEnv(null); ok(adm_env()['key'] === 'unset', 'no setting: environment not set (nobody assumes the server)');
$css = adm_css(); ok(strpos($css, '.admEnv-staging{background:#fde68a') !== false && strpos($css, '.admEnv-production{background:#b91c1c') !== false, 'banner colours: amber for staging, red for production');

// ---- shell markup ----
$render = function (array $user, string $cur, string $body = '<h1>Test</h1>', array $get = []) { $_GET = $get; ob_start(); @adm_page($user, $cur, 'Test page', $body); $_GET = []; return ob_get_clean(); };
$owner = ['id' => 1, 'username' => 'own', 'display_name' => 'Olivia <b>Owner</b>', 'role' => 'owner']; $setEnv('staging'); $h = $render($owner, 'finance', '<h1>Finance</h1>', ['view' => 'revenue']);
ok(strpos($h, '<a class="skip" href="#main">') !== false && strpos($h, '<main id="main"') !== false && strpos($h, 'aria-label="Control Center sections"') !== false && strpos($h, 'id="admMenuBtn"') !== false && strpos($h, 'aria-controls="admNav"') !== false && strpos($h, 'aria-expanded="false"') !== false, 'shell: skip link, main landmark, labelled navigation, menu button with aria-controls and aria-expanded');
ok(strpos($h, 'Olivia &lt;b&gt;Owner&lt;/b&gt;') !== false && strpos($h, '<b>Owner</b>') === false && strpos($h, 'class="role">owner<') !== false, 'the signed-in name and role are always shown and escaped');
ok(strpos($h, 'name="act" value="logout"') !== false && preg_match('#name="_csrf" value="[0-9a-f]{16,}"#', $h) === 1, 'sign-out is a POST form with a CSRF token, in the header on every page');
ok(strpos($h, 'admEnv-staging') !== false && strpos($h, '<details class="admGroup"') !== false && strpos($h, 'data-group="money"') !== false && strpos($h, '<summary>') !== false, 'the environment banner and collapsible groups are rendered');
ok(substr_count($h, 'aria-current="page"') >= 2 && strpos($h, 'is-active') !== false, 'the active module and the active breadcrumb are marked');
ok(strpos($h, '<script src="/assets/js/admin-shell.js" defer></script>') !== false && strpos($h, ' onclick=') === false && !preg_match('/\son[a-z]+="/', $h) && preg_match_all('/<script/', $h) === 2, 'only the shell script is loaded: one external file plus a one-line class switch; no inline event handlers');
ok(strpos($h, '<html lang="en">') !== false && strpos($h, 'name="robots" content="noindex, nofollow"') !== false && strpos($h, 'name="viewport"') !== false, 'language, noindex and viewport are set');
$ed = $render(['id' => 2, 'username' => 'ed', 'display_name' => 'Edith', 'role' => 'editor'], 'tools'); ok(strpos($ed, 'Finance and revenue') === false && strpos($ed, 'Analytics') === false && strpos($ed, 'Legacy admin') === false && strpos($ed, 'AI tool management') !== false && strpos($ed, 'AI Universe review') !== false, 'an editor page contains no link or label for modules outside the role');
$vw = $render(['id' => 3, 'username' => 'vw', 'display_name' => 'Vik', 'role' => 'viewer'], 'dashboard'); ok(strpos($vw, 'Finance and revenue') === false && strpos($vw, 'AI tool management') === false && strpos($vw, 'CRM and leads') !== false, 'a viewer page shows only CRM');
$setEnv(null);
ok(strpos($css, '@media (max-width:900px)') !== false && strpos($css, '.js .admSide{position:fixed') !== false && strpos($css, 'prefers-reduced-motion') !== false && strpos($css, 'min-height:44px') !== false, 'responsive drawer, reduced motion and 44px targets are in the stylesheet');
ok(strpos($css, '.admSide{background:var(--navBg)') !== false && strpos($css, 'prefers-color-scheme:dark') !== false, 'light and dark themes are defined');

// ---- sign-in page ----
$si = adm_signin_html('Sign-in failed. <b>x</b>', 'tok123'); ok(strpos($si, 'name="_login_token" value="tok123"') !== false && strpos($si, 'autocomplete="current-password"') !== false && strpos($si, '<b>x</b>') === false && strpos($si, 'role="alert"') !== false && strpos($si, 'for="admUser"') !== false && strpos($si, 'for="admPw"') !== false, 'sign-in form: token, labels, autocomplete, escaped accessible error');
ok(strpos($si, 'no shared passwords') !== false && strpos(adm_signin_html(), 'role="alert"') === false, 'sign-in says there are no default accounts or shared passwords; no error box without an error');
$ag = (string)file_get_contents("$root/adm_auth.php"); ok(strpos($ag, 'crm_login(') !== false && strpos($ag, 'sec_token_valid') !== false && strpos($ag, 'sec_same_origin') !== false && strpos($ag, 'sec_safe_local_path') !== false && !preg_match('/INSERT\s+INTO|UPDATE\s+crm_users|password_hash\(/i', $ag), 'the gate reuses the existing CRM sign-in, token, origin and redirect checks and creates no accounts or hashes');
ok(!preg_match('/session_name\(|session_start\(/', $ag), 'no second session system is created');

// ---- account page and password change ----
$page = adm_account_body(['id' => 1, 'username' => 'own', 'display_name' => 'Olivia', 'role' => 'owner']); ok(strpos($page, 'Signed in as') !== false && strpos($page, 'Your modules') !== false && strpos($page, 'Finance and revenue') !== false && strpos($page, 'value="account_password"') !== false && strpos($page, 'name="_csrf"') !== false && strpos($page, 'autocomplete="new-password"') !== false && strpos($page, 'Not enabled') !== false, 'account page: identity, modules, password form with CSRF, two-factor not enabled');
$pe = adm_account_body(['id' => 3, 'username' => 'vw', 'display_name' => 'Vik', 'role' => 'viewer']); ok(strpos($pe, 'Finance and revenue') === false && strpos($pe, 'CRM and leads') !== false, 'the account page lists only the role\'s modules');
$pe = adm_account_body(['id' => 1, 'username' => 'o', 'display_name' => 'O', 'role' => 'owner'], [], ['current' => 'The current password is not correct.'], 'x<script>'); ok(strpos($pe, 'aria-invalid="true"') !== false && strpos($pe, '<script>') === false && strpos($pe, 'role="alert"') !== false, 'password errors are accessible and escaped');
ok(strpos(adm_account_body($owner, ['msg' => '<b>x</b>']), '<b>x</b>') === false && strpos(adm_account_body($owner, ['msg' => 'pw_changed']), 'Your password was changed') !== false, 'the flash message comes only from a fixed list');
ok(strpos(adm_account_body($owner), 'value=') === false || !preg_match('/<input[^>]*type="password"[^>]*value=/', adm_account_body($owner)), 'password fields never echo a value');
$good = 'correct horse battery staple';
foreach ([['', 'new'], ['short1', 'new'], [str_repeat('a', 201), 'new'], ['aaaaaaaaaaaaaaaa', 'new'], ['xx-own-xx-longer-phrase', 'new'], ['password1234', 'new'], ['Password-1-abc', 'new'], ['OliviaOwner-secret-1', 'new']] as [$pw, $field]) { $e = adm_password_errors($pw, $pw, 'old-password-value', 'own', 'Olivia'); ok(isset($e[$field]), 'weak password refused: ' . substr($pw, 0, 24)); }
ok(adm_password_errors($good, $good, 'old-password-value', 'own', 'Olivia') === [] && isset(adm_password_errors($good, $good . 'x', 'old-password-value', 'own')['confirm']) && isset(adm_password_errors('old-password-value', 'old-password-value', 'old-password-value', 'own')['new']), 'a long phrase passes; a mismatch and reuse of the current password are refused');
$st = new AdmAccountMemoryStore([1 => password_hash('old-password-value', PASSWORD_DEFAULT), 2 => password_hash('other-password-value', PASSWORD_DEFAULT)]); $audit = []; $au = function (string $a, string $s) use (&$audit) { $audit[] = [$a, $s]; }; $never = fn($b) => false; $u1 = ['id' => 1, 'username' => 'own', 'display_name' => 'Olivia', 'role' => 'owner'];
$r = adm_account_change_password($st, $u1, ['current' => 'WRONG-password', 'new' => $good, 'confirm' => $good], $au, $never); ok(!$r['ok'] && $r['code'] === 422 && password_verify('old-password-value', $st->hash(1)) && in_array('account_password_failed', array_column($audit, 0), true), 'a wrong current password changes nothing and is audited');
$r = adm_account_change_password($st, $u1, ['current' => 'old-password-value', 'new' => 'short', 'confirm' => 'short'], $au, $never); ok(!$r['ok'] && isset($r['errors']['new']) && password_verify('old-password-value', $st->hash(1)), 'a weak new password is refused and the old one still works');
$r = adm_account_change_password($st, $u1, ['current' => 'old-password-value', 'new' => $good, 'confirm' => $good], $au, $never); ok($r['ok'] && $r['code'] === 303 && password_verify($good, $st->hash(1)) && !password_verify('old-password-value', $st->hash(1)) && in_array('account_password_changed', array_column($audit, 0), true), 'a correct change works, the old password stops working, and it is audited');
ok(password_verify('other-password-value', $st->hash(2)), 'another account is never touched');
$r = adm_account_change_password($st, $u1, ['id' => 2, 'uid' => 2, 'user_id' => 2, 'current' => $good, 'new' => 'another long passphrase 42', 'confirm' => 'another long passphrase 42'], $au, $never); ok($r['ok'] && password_verify('other-password-value', $st->hash(2)) && password_verify('another long passphrase 42', $st->hash(1)), 'an account id in the request is ignored: only the signed-in user is changed');
$r = adm_account_change_password($st, ['id' => 0, 'username' => 'x'], ['current' => 'a', 'new' => $good, 'confirm' => $good], $au, $never); ok(!$r['ok'] && $r['code'] === 403, 'no signed-in user: refused');
$r = adm_account_change_password($st, ['id' => 99, 'username' => 'ghost'], ['current' => 'a', 'new' => $good, 'confirm' => $good], $au, $never); ok(!$r['ok'] && $r['code'] === 422, 'an unknown or inactive account cannot change a password');
$n = 0; $lim = function ($b) use (&$n) { return ++$n > 5; }; for ($i = 0; $i < 7; $i++) $r = adm_account_change_password($st, $u1, ['current' => 'nope', 'new' => $good, 'confirm' => $good], $au, $lim); ok(!$r['ok'] && $r['code'] === 429 && in_array('account_password_rate_limited', array_column($audit, 0), true), 'repeated attempts are rate limited (429) and audited');
ok(!preg_match('/\$post\[.(?:id|uid|user_id).\]/', (string)file_get_contents("$root/adm_account.php")), 'the account code never reads an account id from the request');
$ac = (string)file_get_contents("$root/admin-center.php"); ok(strpos($ac, 'crm_csrf_ok()') < strpos($ac, "'account_'") && strpos($ac, "'account_'") !== false, 'password changes reach the handler only after the CSRF and same-origin check');
ok(strpos($ac, 'session_regenerate_id(true)') !== false && strpos($ac, "\$_SESSION['crm_csrf'] = bin2hex(random_bytes(16))") !== false, 'after a password change the session id and CSRF token are renewed');
ok(strpos($ac, 'adm_gate()') !== false && strpos($ac, 'crm_gate()') === false, 'the Control Center uses the single gate');

// ---- static ----
$js = (string)file_get_contents("$root/assets/js/admin-shell.js"); ok(strpos($js, "e.key === 'Escape'") !== false && strpos($js, 'aria-expanded') !== false && strpos($js, 'focus') !== false && strpos($js, 'localStorage') !== false && !preg_match('/fetch\(|XMLHttpRequest|sendBeacon|eval\(|document\.write/', $js), 'the shell script handles Escape, focus and aria-expanded, remembers collapsed groups locally, and makes no network calls');
$sec = json_decode((string)file_get_contents("$root/tests/security_manifest.json"), true)['files'] ?? []; foreach (['adm_nav.php', 'adm_auth.php', 'adm_account.php'] as $f) ok(($sec[$f] ?? '') === 'lib', "$f is in the security manifest");
$perms = adm_role_perms(); ok(count(array_filter($perms, fn($p) => in_array('account', $p, true))) === 5 && !in_array('finance', $perms['editor'], true) && !in_array('analytics', $perms['editor'], true) && !in_array('tools_publish', $perms['editor'], true) && array_keys($perms) === ['owner', 'sales', 'viewer', 'editor', 'verifier'], 'every role may manage its own account; no other permission was added to any role');
ok(array_diff($perms['owner'], ['center', 'account', 'crm', 'universe', 'legacy', 'analytics', 'tools', 'tools_publish', 'finance', 'advertising', 'operations', 'performance', 'access']) === [], 'the owner permission set is unchanged apart from the account page');
echo "\nPASSED: $pass  FAILED: $fail\n"; exit($fail ? 1 : 0);
